function shortPreset(name: string): string {
  const separator = name.indexOf(' @');
  return separator < 0 ? name : name.slice(0, separator);
}

// The settings in force that differ from the presets: the project's own,
// and those an object, part, modifier or height range sets for itself.
// Support painting and blockers set no setting and are not counted.
export function changedSettingCount(context: WorkspaceContext): number {
  return context.presetDeltas.length + (context.appliedSetup?.localOverrides ?? []).filter((local) => local.key).length;
}

// The process with the first filament and how many more, then how many
// settings differ from the presets: "0.20mm Standard with Generic ABS and 2
// other filaments. 7 settings differ from the presets."
export function presetsLine(context: WorkspaceContext): string {
  const process = context.printer.process.trim();
  if (!process) return '';
  const filaments = context.setupIdentity?.filaments ?? [];
  const first = (filaments[0]?.preset || context.printer.filament).trim();
  const more = filaments.length - 1;
  const filament = first
    ? ` with ${shortPreset(first)}${more > 0 ? ` and ${more} other ${more === 1 ? 'filament' : 'filaments'}` : ''}` : '';
  const changed = changedSettingCount(context);
  const differ = changed > 0 ? ` ${changed} ${changed === 1 ? 'setting differs' : 'settings differ'} from the presets.` : '';
  return `${shortPreset(process)}${filament}.${differ}`;
}

// The app's own mark that the project moved on since the plan was recorded,
// which only the agent recording it again clears.
export function planInDoubt(context: WorkspaceContext): boolean {
  return !!context.planHeadline.trim() && context.planValidity === 'needs_reassessment';
}

// The plan line's annotation: what moved since the plan was recorded, in the
// words the host wrote for it ("Filament changed to Generic ABS by hand"),
// with the Check plan link beside it; failing that, a calibration test whose
// steps the file lost, since in a calibration chat the test is the plan.
export function planNote(context: WorkspaceContext): string {
  if (planInDoubt(context))
    return context.planInvalidatedBy || 'Plan needs another look';
  return testStepsLost(context);
}

